-- Phase 1: identity, roles, sessions and a transactional email outbox.
-- IDs are UUIDv7 generated by the application, not database-generated UUIDv4.

CREATE FUNCTION valid_person_name(value text) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $fn$
  SELECT COALESCE(
    char_length(value) BETWEEN 1 AND 120
    AND value = btrim(value,
      U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\200B\FEFF')
    AND char_length(translate(value,
      U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\200B\FEFF\200C\200D\2060', '')) > 0
    AND NOT EXISTS (
      SELECT 1 FROM (SELECT generate_series(1,31) AS n UNION ALL SELECT generate_series(127,159)
                     UNION ALL SELECT 8232 UNION ALL SELECT 8233) AS controls
      WHERE position(chr(controls.n) IN value) > 0
    ), false)
$fn$;

CREATE TABLE users (
  id uuid PRIMARY KEY,
  email_original text,
  email_canonical text UNIQUE,
  email_verified_at timestamptz,
  password_hash text,
  first_name text,
  last_name text,
  locale text NOT NULL DEFAULT 'de-DE',
  status text NOT NULL CHECK (status IN ('pending_activation','active','blocked','deletion_requested','deleted')),
  last_login_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT users_name_status_check CHECK (
    (status = 'deleted' AND first_name IS NULL AND last_name IS NULL)
    OR (status <> 'deleted' AND valid_person_name(first_name) AND valid_person_name(last_name))
  ),
  CONSTRAINT users_email_check CHECK (
    status = 'deleted' OR (email_original IS NOT NULL AND email_canonical IS NOT NULL
      AND octet_length(email_original) BETWEEN 3 AND 254 AND octet_length(email_canonical) BETWEEN 3 AND 254)
  ),
  CONSTRAINT users_activation_check CHECK (status <> 'active' OR (password_hash IS NOT NULL AND email_verified_at IS NOT NULL))
);

CREATE TABLE billing_profiles (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  company text,
  first_name text NOT NULL CHECK (valid_person_name(first_name)),
  last_name text NOT NULL CHECK (valid_person_name(last_name)),
  street text NOT NULL, street_extra text, postal_code text NOT NULL, city text NOT NULL,
  region text, country char(2) NOT NULL, vat_id text, is_default boolean NOT NULL DEFAULT false,
  archived_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX billing_profiles_user_id_idx ON billing_profiles(user_id);
CREATE UNIQUE INDEX billing_profiles_one_default ON billing_profiles(user_id) WHERE is_default AND archived_at IS NULL;

CREATE TABLE roles (
  id uuid PRIMARY KEY, key text NOT NULL UNIQUE, name text NOT NULL, is_system boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE permissions (
  id uuid PRIMARY KEY, key text NOT NULL UNIQUE, description text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE role_permissions (
  role_id uuid NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
  permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE RESTRICT,
  granted_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(role_id, permission_id)
);
CREATE INDEX role_permissions_permission_id_idx ON role_permissions(permission_id);
CREATE TABLE user_roles (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  role_id uuid NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
  granted_by uuid REFERENCES users(id) ON DELETE RESTRICT,
  granted_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, role_id)
);
CREATE INDEX user_roles_role_id_idx ON user_roles(role_id);
CREATE INDEX user_roles_granted_by_idx ON user_roles(granted_by);

CREATE TABLE user_mfa_factors (
  id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  type text NOT NULL CHECK (type = 'totp'),
  status text NOT NULL CHECK (status IN ('pending','active','revoked')),
  secret_ciphertext bytea NOT NULL, key_id text NOT NULL,
  confirmed_at timestamptz, last_used_at timestamptz, last_accepted_step bigint CHECK (last_accepted_step >= 0),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX user_mfa_factors_user_id_idx ON user_mfa_factors(user_id);
CREATE UNIQUE INDEX user_mfa_one_open_factor ON user_mfa_factors(user_id, type) WHERE status IN ('pending','active');
CREATE TABLE mfa_recovery_codes (
  id uuid PRIMARY KEY, factor_id uuid NOT NULL REFERENCES user_mfa_factors(id) ON DELETE RESTRICT,
  code_hash bytea NOT NULL UNIQUE, used_at timestamptz, expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX mfa_recovery_codes_factor_id_idx ON mfa_recovery_codes(factor_id);

CREATE TABLE auth_sessions (
  id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  kind text NOT NULL CHECK (kind IN ('preauth','participant','backoffice')),
  token_hash bytea NOT NULL UNIQUE, csrf_secret_hash bytea NOT NULL,
  mfa_verified_at timestamptz, reauthenticated_at timestamptz,
  last_seen_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz,
  ip_hmac bytea, user_agent_hmac bytea,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT session_backoffice_mfa CHECK (kind <> 'backoffice' OR mfa_verified_at IS NOT NULL),
  CONSTRAINT session_expiry CHECK (expires_at > created_at)
);
CREATE INDEX auth_sessions_user_id_idx ON auth_sessions(user_id);
CREATE INDEX auth_sessions_expires_at_idx ON auth_sessions(expires_at);
CREATE TABLE account_tokens (
  id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  purpose text NOT NULL CHECK (purpose IN ('activation','email_verify','password_reset','email_change')),
  token_hash bytea NOT NULL UNIQUE, target_email_original text, target_email_canonical text,
  expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT token_target_check CHECK (
    (purpose = 'email_change' AND target_email_original IS NOT NULL AND target_email_canonical IS NOT NULL)
    OR (purpose <> 'email_change' AND target_email_original IS NULL AND target_email_canonical IS NULL)
  )
);
CREATE INDEX account_tokens_user_id_purpose_idx ON account_tokens(user_id, purpose);

CREATE TABLE audit_events (
  id uuid PRIMARY KEY, actor_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
  origin text NOT NULL CHECK (origin IN ('user','system','bootstrap','provider')),
  action text NOT NULL, target_type text NOT NULL, target_ref text NOT NULL,
  before_safe jsonb, after_safe jsonb, reason_code text, request_id uuid, ip_hmac bytea,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX audit_events_actor_user_id_idx ON audit_events(actor_user_id);
CREATE INDEX audit_events_target_type_target_ref_idx ON audit_events(target_type, target_ref);

CREATE TABLE email_templates (
  id uuid PRIMARY KEY, key text NOT NULL, locale text NOT NULL, status text NOT NULL CHECK (status IN ('active','inactive')),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(key, locale)
);
CREATE TABLE email_template_versions (
  id uuid PRIMARY KEY, template_id uuid NOT NULL REFERENCES email_templates(id) ON DELETE RESTRICT,
  version integer NOT NULL CHECK (version > 0), state text NOT NULL CHECK (state IN ('draft','published','retired')),
  subject_template text NOT NULL, body_html_template text NOT NULL, body_text_template text NOT NULL,
  allowed_variables jsonb NOT NULL, created_by uuid REFERENCES users(id) ON DELETE RESTRICT, published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(template_id, version)
);
CREATE INDEX email_template_versions_created_by_idx ON email_template_versions(created_by);
CREATE UNIQUE INDEX email_template_versions_one_published ON email_template_versions(template_id) WHERE state = 'published';

CREATE TABLE email_outbox (
  id uuid PRIMARY KEY, template_version_id uuid NOT NULL REFERENCES email_template_versions(id) ON DELETE RESTRICT,
  purpose text NOT NULL CHECK (purpose = 'transaction'), user_id uuid REFERENCES users(id) ON DELETE RESTRICT,
  to_email text NOT NULL, variables_public jsonb NOT NULL,
  variables_secret_ciphertext bytea, secret_key_id text, secret_delete_after timestamptz,
  idempotency_key text NOT NULL UNIQUE, status text NOT NULL CHECK (status IN ('queued','sending','accepted','delivered','failed','suppressed')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), scheduled_at timestamptz NOT NULL, sent_at timestamptz,
  provider text, provider_message_id text, last_error_safe text,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT outbox_secret_check CHECK (
    (variables_secret_ciphertext IS NULL AND secret_key_id IS NULL AND secret_delete_after IS NULL)
    OR (variables_secret_ciphertext IS NOT NULL AND secret_key_id IS NOT NULL AND secret_delete_after IS NOT NULL)
  )
);
CREATE INDEX email_outbox_template_version_id_idx ON email_outbox(template_version_id);
CREATE INDEX email_outbox_user_id_idx ON email_outbox(user_id);
CREATE INDEX email_outbox_status_scheduled_at_idx ON email_outbox(status, scheduled_at);
CREATE UNIQUE INDEX email_outbox_provider_message_idx ON email_outbox(provider, provider_message_id) WHERE provider_message_id IS NOT NULL;

CREATE TABLE automation_jobs (
  id uuid PRIMARY KEY, kind text NOT NULL, ref_type text NOT NULL, ref_id uuid,
  payload_schema_version smallint NOT NULL, payload jsonb NOT NULL,
  idempotency_key text NOT NULL UNIQUE,
  status text NOT NULL CHECK (status IN ('queued','waiting_for_data','running','succeeded','failed','cancelled')),
  wait_reason text, attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), max_attempts integer NOT NULL CHECK (max_attempts > 0),
  run_after timestamptz NOT NULL, lease_until timestamptz, finished_at timestamptz, last_error_safe text,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX automation_jobs_status_run_after_idx ON automation_jobs(status, run_after);
CREATE TABLE automation_job_attempts (
  id uuid PRIMARY KEY, automation_job_id uuid NOT NULL REFERENCES automation_jobs(id) ON DELETE RESTRICT,
  attempt_no integer NOT NULL CHECK (attempt_no > 0), started_at timestamptz NOT NULL, finished_at timestamptz NOT NULL,
  result text NOT NULL CHECK (result IN ('succeeded','failed','cancelled')), error_safe text,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(automation_job_id, attempt_no)
);
